{"file_path":"/work/tests/test_spec.py","content":""""Regression tests for the behavior defined in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("a", 1, None)]) == 0.0


def test_conversion_rate_empty_is_float_zero():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session(str(i), 1, False) for i in range(3)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    result = pooled_conversion_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4, 8], 2, 12), ([1, 2, 4], 1, 4), ([1, 2], 0, 0),
     ([1, 2], 2, 3), ([1, 2], 5, 3), ([], 0, 0), ([], 3, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


@pytest.mark.parametrize("flag, expected", [("1", True), ("0", False), ("", None)])
def test_parse_session_log_flags_and_field_whitespace(flag, expected):
    result = parse_session_log([f"  x1 \t, -3 , {flag} \n"])
    assert result == [session("x1", -3, expected)]
    assert result[0]["converted"] is expected


def test_parse_session_log_skips_blank_and_comment_lines():
    lines = ["", "\n", " \t\n", "# comment", "  \t# comment,with,commas", "x,1,0"]
    assert parse_session_log(lines) == [session("x", 1, False)]
    assert parse_session_log(lines[:-1]) == []


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x", "x,no,1", "x,1.5,0", "x,,1"])
@pytest.mark.parametrize("prefix", [[], ["", "  # skipped", "ok,1,1", " \t"]])
def test_parse_session_log_errors_include_original_line_number(bad_line, prefix):
    with pytest.raises(ValueError, match=rf"\bline {len(prefix) + 1}\b"):
        parse_session_log(prefix + [bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        session("a", 9, True),
        session("z", 1, True),
        session("b", 2, False),
        session("a", 2, False),
        session("z", 3, None),
        session("a", 2, True),
    ]
    # Input order, not the largest day or conversion flag, determines the winner.
    assert dedupe_sessions(events) == [events[5], events[2], events[4]]


def test_dedupe_sessions_empty():
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_and_gaps():
    events = [
        session("before", 0, True),
        session("a", 1, True),
        session("b", 1, True),
        session("c", 2, False),
        session("d", 2, None),
        session("e", 4, True),
        session("after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []


@pytest.mark.parametrize("start, end, expected", [(1, 3, [0, 0, 0]), (-1, 1, [0, 0, 0]), (2, 1, [])])
def test_daily_conversion_counts_without_sessions(start, end, expected):
    assert daily_conversion_counts([], start, end) == expected


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (4, 2), (20, 2)])
def test_campaign_summary_pooled_rounded_rate_and_calendar_window(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "empty": [],
        "large": [
            session("b", 4, False),
            session("c", 3, True),
            session("d", 1, None),
            session("e", 1, False),
            session("f", 1, False),
        ],
    }
    assert campaign_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [session("z", 1, True), session("z2", 1, False)],
        "empty": [],
        "a": [session("a", 1, True), session("a2", 1, None)],
        "winner": [session("w", 1, True)],
        "zero": [session("n", 1, None)],
    }
    assert top_converting_groups(groups, 2) == ["winner", "a"]
    assert top_converting_groups(groups, 10) == ["winner", "a", "z", "zero"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({"empty": []}, 3) == []
    assert top_converting_groups({}, 3) == []


def test_conversion_rate_by_group_sorted_keys_and_empty_groups():
    groups = {
        "z": [session("a", 1, True), session("b", 1, None)],
        "b": [session("c", 1, False)],
        "a": [],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": None, "b": 0.0, "z": 0.5}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, -2, 0], 0), ([1, 2, 3], 3),
     ([1, 0, 2, 3, 0, 4], 2), ([1, -1, 2], 1), ([0, 1, 2, 3], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
